<template>
  <div class="page-content">

    <h1 class="w3-text-teal">
      Danh sách Icon
    </h1>

    <!-- Tìm kiếm -->
    <div class="mb-3">
      <b-form-input
        v-model="keyword"
        placeholder="Tìm icon..."
        autocomplete="off"
      />
    </div>

    <div class="icon-grid">

      <div
        v-for="item in filteredIcons"
        :key="item"
        class="icon-item"
        @click="copyIcon(item)"
      >

        <b-icon
          :icon="item"
          font-scale="2"
        />

        <div class="icon-name">
          {{ item }}
        </div>

      </div>

    </div>

    <div
      v-if="copied"
      class="copy-message"
    >
      Đã copy:
      <strong>{{ copied }}</strong>
    </div>

  </div>
</template>

<script>
export default {
  name: 'IconList',

  data() {
    return {

      keyword: '',

      copied: '',

      icons: [

        // ======================
        // Chung
        // ======================

        'house',
        'house-fill',
        'gear',
        'gear-fill',
        'tools',
        'wrench',
        'sliders',

        // ======================
        // User
        // ======================

        'person',
        'person-fill',
        'people',
        'people-fill',
        'person-plus',
        'person-dash',
        'person-check',
        'person-x',

        // ======================
        // CRUD
        // ======================

        'plus',
        'plus-circle',
        'plus-circle-fill',

        'pencil',
        'pencil-square',

        'trash',
        'trash-fill',

        'save',
        'check',
        'check-circle',
        'check-circle-fill',

        'x',
        'x-circle',
        'x-circle-fill',

        // ======================
        // Search
        // ======================

        'search',
        'filter',
        'funnel',
        'funnel-fill',

        // ======================
        // Navigation
        // ======================

        'arrow-left',
        'arrow-right',
        'arrow-up',
        'arrow-down',

        'chevron-left',
        'chevron-right',
        'chevron-up',
        'chevron-down',

        // ======================
        // Menu
        // ======================

        'list',
        'list-ul',
        'list-task',

        'three-dots',
        'three-dots-vertical',

        // ======================
        // File
        // ======================

        'file',
        'file-earmark',
        'file-earmark-text',
        'file-earmark-pdf',
        'file-earmark-spreadsheet',

        'folder',
        'folder-fill',
        'folder2-open',

        // ======================
        // Download / Upload
        // ======================

        'download',
        'upload',
        'cloud-download',
        'cloud-upload',

        // ======================
        // Email
        // ======================

        'envelope',
        'envelope-fill',

        // ======================
        // Phone
        // ======================

        'telephone',
        'telephone-fill',

        // ======================
        // Calendar
        // ======================

        'calendar',
        'calendar-date',
        'calendar-check',
        'calendar-event',

        // ======================
        // Camera / Image
        // ======================

        'camera',
        'camera-fill',
        'image',
        'images',

        // ======================
        // Status
        // ======================

        'info-circle',
        'info-circle-fill',

        'exclamation-circle',
        'exclamation-triangle',

        'question-circle',

        // ======================
        // Eye
        // ======================

        'eye',
        'eye-fill',
        'eye-slash',
        'eye-slash-fill',

        // ======================
        // Lock
        // ======================

        'lock',
        'lock-fill',
        'unlock',
        'unlock-fill',

        // ======================
        // Database
        // ======================

        'server',
        'hdd',
        'database',

        // ======================
        // Network
        // ======================

        'wifi',
        'wifi-off',
        'globe',

        // ======================
        // Misc
        // ======================

        'star',
        'star-fill',
        'heart',
        'heart-fill',

        'bookmark',
        'bookmark-fill',

        'printer',
        'clipboard',
        'clipboard-check',

        'clock',
        'clock-fill',

        'link',
        'paperclip',

        'cart',
        'cart-fill',

        'bell',
        'bell-fill',

        'box-arrow-right',
        'box-arrow-in-right'

      ]

    }
  },

  computed: {

    filteredIcons() {

      const keyword =
        this.keyword
          .trim()
          .toLowerCase()

      if (!keyword) {
        return this.icons
      }

      return this.icons.filter(x =>
        x.toLowerCase().includes(keyword)
      )

    }

  },

  methods: {

    copyIcon(icon) {

      const code =
        `<b-icon icon="${icon}"></b-icon>`

      if (
        navigator.clipboard &&
        navigator.clipboard.writeText
      ) {

        navigator.clipboard.writeText(code)

      }

      this.copied = code

      setTimeout(() => {
        this.copied = ''
      }, 2000)

    }

  }

}
</script>
